#include <bits/stdc++.h>

using namespace std;

int main() {
    vector<vector<int>> v(4, vector<int>(4));
    set<pair<int, int>> st;

    int x = 0, y = 0;
    bool check = true;

    for (int i = 0; i < 4; i++) {
        scanf("%d %d %d %d", &v[i][0], &v[i][1], &v[i][2], &v[i][3]);

        if (v[i][0] != v[i][2] && v[i][1] != v[i][3])
            check = false;

        if (v[i][0] == v[i][2])
            x++;
        else if (v[i][1] == v[i][3])
            y++;

        st.insert({v[i][0], v[i][1]});
        st.insert({v[i][2], v[i][3]});
    }

    if (!check || st.size() != 4 || x != 2 || y != 2) {
        cout << "NO";
        return 0;
    }

    vector<pair<int, int>> p(st.begin(), st.end());

    if (p[0].first != p[1].first ||
        p[2].first != p[3].first ||
        p[0].first == p[2].first) {
        check = false;
    }

    for (auto& point : p)
        swap(point.first, point.second);

    sort(p.begin(), p.end());

    if (p[0].first != p[1].first ||
        p[2].first != p[3].first ||
        p[0].first == p[2].first) {
        check = false;
    }

    cout << (check ? "YES" : "NO");
    return 0;
}

